const token=prompt('Enter the admin token'),auth={Authorization:'Bearer '+token,'Content-Type':'application/json'},$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function req(u,b){const r=await fetch(u,{method:b?'POST':'GET',headers:auth,body:b?JSON.stringify(b):undefined}),d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d}function toggle(b){const c=b.parentElement.parentElement.querySelector(':scope > .tree-children');if(!c)return;b.classList.toggle('closed');c.hidden=b.classList.contains('closed');b.textContent=b.classList.contains('closed')?'›':'∨'}function eventNode(e){return `<div class="tree-node event-node"><div class="tree-line"><button class="tree-toggle">∨</button><span>${esc(e.stage||'Heat')}</span></div><div class="tree-children"><div class="tree-node"><div class="tree-line"><button class="tree-toggle">∨</button><span>${esc(e.name)}</span></div><div class="tree-children leaf">– Visibility: <button class="visibility" data-id="${esc(e.id)}">${e.visible?'True':'False'}</button></div></div></div></div>`}async function render(){try{const d=await req('/api/admin/status'),p=d.meta.feed_paused==='true',f=d.file;$('#export-dir').value='RACE_EXPORT_DIR='+d.sourceConfig.hostDirectory;$('#export-filename').value='RACE_EXPORT_FILENAME='+d.sourceConfig.filename;$('#app-version').textContent='Version '+d.version;$('#file-status').textContent=f.exists?`Reading ${f.configured} · ${f.bytes} bytes`:`Waiting for ${f.configured}`;$('#import-status').textContent=d.meta.last_error?'Last error: '+d.meta.last_error:'Last successful import: '+(d.meta.last_import||'waiting');$('#event-status').value=d.meta.status||'Live';$('#event-status').onchange=()=>req('/api/admin/status',{status:$('#event-status').value});$('#feed-toggle').textContent=p?'Start live updates':'Stop live updates ('+d.pollSeconds+'s)';$('#feed-toggle').onclick=async()=>{await req('/api/admin/feed',{running:p});render()};const names=d.tournaments.map(t=>t.name),unassigned=d.events.filter(e=>!names.includes(e.tournament));$('#event-list').innerHTML=`<div class="tree-toolbar"><input id="new-tournament" placeholder="New tournament"><button class="tree-add" id="add-tournament">+</button></div><div class="object-tree">${d.tournaments.map(t=>`<div class="tree-node tournament"><div class="tree-line"><button class="tree-toggle">∨</button><strong>${esc(t.name)}</strong></div><div class="tree-children">${d.events.filter(e=>e.tournament===t.name).map(eventNode).join('')||'<span class="empty-tree">No heats</span>'}<button class="tree-add assign-open" data-tournament="${t.id}">+</button><div class="assign-box" hidden><select>${unassigned.map(e=>`<option value="${esc(e.id)}">${esc(e.stage||e.name)} · ${esc(e.name)}</option>`).join('')}</select><button class="btn assign">Assign</button></div></div></div>`).join('')}<div class="tree-node"><div class="tree-line"><button class="tree-toggle closed">›</button><strong>Unassigned heats</strong></div><div class="tree-children" hidden>${unassigned.map(eventNode).join('')||'<span class="empty-tree">None</span>'}</div></div></div>`;$('#add-tournament').onclick=async()=>{const n=$('#new-tournament').value.trim();if(n){await req('/api/admin/tournaments',{name:n});render()}};$('#event-list').querySelectorAll('.tree-toggle').forEach(b=>b.onclick=()=>toggle(b));$('#event-list').querySelectorAll('.visibility').forEach(b=>b.onclick=async()=>{await req('/api/admin/events/'+encodeURIComponent(b.dataset.id),{visible:b.textContent!=='True'});render()});$('#event-list').querySelectorAll('.assign-open').forEach(b=>b.onclick=()=>{const box=b.nextElementSibling;box.hidden=!box.hidden});$('#event-list').querySelectorAll('.assign').forEach(b=>b.onclick=async()=>{const box=b.parentElement,t=d.tournaments.find(x=>x.id===+box.parentElement.parentElement.querySelector('.assign-open').dataset.tournament),e=d.events.find(x=>x.id===box.querySelector('select').value);if(e){await req('/api/admin/events/'+encodeURIComponent(e.id),{mapping:true,tournament:t.name,stage:e.stage||e.name,name:e.name});render()}})}catch(e){$('#event-list').textContent=e.message}}render();



